#!/bin/bash

# Checks that the checked-in consistency checkers are what Kater generates
#
# This program is dual-licensed under the Apache License 2.0 and the MIT License.
# You may choose to use, distribute, or modify this software under either license.
#
# Apache License 2.0:
#     http://www.apache.org/licenses/LICENSE-2.0
#
# MIT License:
#     https://opensource.org/licenses/MIT

# genmc/genmc/Models/<MODEL>Checker.{hpp,cpp} are generated by Kater from its
# kat files (scripts/lkmm/kater-export.sh). A change by hand is lost at the
# next export, and so is a change to a kat file or to Kater's printer that is
# not exported: the files are regenerated and compared, but for the line
# naming the Kater revision. A change to a checker goes into Kater (its kat
# file, or its printer), and the checkers are exported again. Skipped
# (status 77) without a built Kater. ctest target "kater-drift".
#
#   KATER_SRC=<kater checkout> [KATER=<kater binary>] scripts/check-kater-drift.sh

DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"
ROOT="${DIR}/.."
KATER_SRC="${KATER_SRC:-${HOME}/.local/src/kater}"
KATER="${KATER:-${KATER_SRC}/Release/kater}"
MODELS=(sc tso ra rc11 imm lkmm)

if [ ! -x "${KATER}" ] || [ ! -d "${KATER_SRC}/kat" ]; then
	echo "skip: no Kater (KATER_SRC=${KATER_SRC}, KATER=${KATER})"
	exit 77
fi

out="$(mktemp -d)"
trap 'rm -rf "${out}"' EXIT
KATER_SRC="${KATER_SRC}" KATER="${KATER}" \
	"${DIR}/lkmm/kater-export.sh" -o "${out}" "${MODELS[@]}" > "${out}/export.log" 2>&1 ||
	{ cat "${out}/export.log"; exit 1; }

status=0
for m in "${MODELS[@]}"; do
	for f in "${m^^}Checker.hpp" "${m^^}Checker.cpp"; do
		checked="${ROOT}/genmc/genmc/Models/${f}"
		if diff -q <(grep -v '^ \* From kat/' "${checked}") \
		     <(grep -v '^ \* From kat/' "${out}/${f}") > /dev/null; then
			echo "ok   ${f}"
		else
			echo "FAIL ${f} differs from Kater's output (checked in: $(grep -m1 '^ \* From kat/' \
				"${ROOT}/genmc/genmc/Models/${m^^}Checker.hpp" | sed 's/^ \* //'))"
			diff <(grep -v '^ \* From kat/' "${checked}") <(grep -v '^ \* From kat/' "${out}/${f}") |
				head -10
			status=1
		fi
	done
done
exit ${status}
